const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const out = [];

for (const item of $input.all()) {
  const m = item.json;

  if (!m || !m.deliveryId || !m.event) continue;
  if (store.seen[m.deliveryId]) continue;
  store.seen[m.deliveryId] = Date.now();

  const keys = Object.keys(store.seen);
  if (keys.length > 500) {
    for (const k of keys.slice(0, keys.length - 500)) delete store.seen[k];
  }

  out.push(m);
}

return out;

const esc = (s) => String(s ?? "").replace(/&/g, "&").replace(/</g, "<").replace(/>/g, ">").replace(/"/g, """);

const out = [];

for (const item of $input.all()) {
  const m = item.json;
  if (m.event !== 'user.invited') continue;

  const d = m.data || {};
  const chatId = d.telegram && d.telegram.telegramId;
  if (!chatId) continue;

  const text = '<b>Undangan Akses</b>\n' +
    'Halo <b>' + esc(d.user && d.user.name) + '</b>,\n' +
    'Akun <b>' + esc(d.user && d.user.email) + '</b> (role: ' + esc(d.user && d.user.role) + ') telah dibuat.\n' +
    'Silakan login di aplikasi After-Sales.';

  out.push({ json: Object.assign({}, m, { _chatId: chatId, _text: text }) });
}

return out;

const esc = (s) => String(s ?? "").replace(/&/g, "&").replace(/</g, "<").replace(/>/g, ">").replace(/"/g, """);
const ADMIN_CHAT_ID = 'REPLACE_WITH_ADMIN_GROUP_CHAT_ID';

const out = [];

for (const item of $input.all()) {
  const m = item.json;
  if (m.event !== 'ticket.claimed') continue;

  const d = m.data || {};
  let chatId = (d.group && d.group.chatId) || ADMIN_CHAT_ID;
  let fallbackNote = '';
  if (!(d.group && d.group.chatId)) {
    fallbackNote = '\n<i>(grup tiket tidak ditemukan - fallback grup admin)</i>';
  }
  const text = '<b>Tiket diklaim</b>\n' +
    'Tiket <code>' + esc(d.ticketId) + '</code> diklaim oleh <b>' + esc(d.claimer && d.claimer.name) + '</b>.' + fallbackNote;

  out.push({ json: Object.assign({}, m, { _chatId: chatId, _text: text }) });
}

return out;

const esc = (s) => String(s ?? "").replace(/&/g, "&").replace(/</g, "<").replace(/>/g, ">").replace(/"/g, """);

const out = [];

for (const item of $input.all()) {
  const m = item.json;
  if (m.event !== 'ticket.member_added') continue;

  const d = m.data || {};
  const chatId = d.addedMember && d.addedMember.telegram && d.addedMember.telegram.telegramId;
  if (!chatId) continue;

  const text = '<b>Kamu ditambahkan ke tiket</b>\n' +
    'Tiket <code>' + esc(d.ticketId) + '</code> - ditambahkan oleh <b>' + esc(d.addedBy) + '</b>.';

  out.push({ json: Object.assign({}, m, { _chatId: chatId, _text: text }) });
}

return out;

