const out = [];

for (const item of $input.all()) {
  const m = item.json;
  if (m.event !== 'otp.password_reset') continue;

  const d = m.data || {};
  const chatId = d.telegram && d.telegram.telegramId;
  if (!chatId) continue;

  const text = '<b>Reset Password</b>\n' +
    'OTP kamu: <code>' + esc(d.otp) + '</code>\n' +
    'Berlaku ' + esc(d.expiresInMinutes) + ' menit. Jangan bagikan ke siapa pun.';

  out.push({ json: Object.assign({}, m, { _chatId: chatId, _text: text }) });
}

return out;
